import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Angoli fra rette tagliate da una trasversale","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffc.md","filePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffc.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/ff/ffc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="angoli-fra-rette-tagliate-da-una-trasversale" tabindex="-1">Angoli fra rette tagliate da una trasversale <a class="header-anchor" href="#angoli-fra-rette-tagliate-da-una-trasversale" aria-label="Permalink to “Angoli fra rette tagliate da una trasversale”">​</a></h1><p>Il criterio che useremo per caratterizzare le rette parallele sarà quello che coinvolge gli angoli che tali rette fanno con una trasversale, pertanto ora dovremo dare un nome a tali angoli per poterli usare; tali nomi però andranno bene anche se le rette non sono parallele. Per semplicità indico ogni angolo con un numero.</p><blockquote><p><strong>Nota:</strong> che le rette <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>a</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{a}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="color:red;">a</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>b</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{b}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="color:red;">b</span></span></span></span> dividono il piano in due semipiani esterni ed una striscia interna fra le due rette.</p><p>Chiameremo [interni]{.text-red} gli angoli che si trovano dentro la striscia.</p><p>Chiameremo [esterni]{.text-red} quelli che si trovano fuori della striscia.</p><p>La retta <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>t</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{t}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6151em;"></span><span class="mord mathnormal" style="color:red;">t</span></span></span></span> divide il piano in due parti.</p><p>Chiameremo [coniugati]{.text-red} gli angoli che stanno dalla stessa parte.</p><p>Chiameremo [alterni]{.text-red} gli angoli che stanno da parti opposte rispetto alla retta <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>t</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{t}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6151em;"></span><span class="mord mathnormal" style="color:red;">t</span></span></span></span>.</p><p>Infine: chiameremo [corrispondenti]{.text-red} gli angoli che si trovano contemporaneamente sopra oppure sotto le rette <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>a</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{a}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="color:red;">a</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>b</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{b}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="color:red;">b</span></span></span></span> (intuitivamente: tali che trascinando la retta <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>b</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{b}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="color:red;">b</span></span></span></span> sopra la retta <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle mathcolor="red"><mi>a</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{a}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="color:red;">a</span></span></span></span> si sovrappongono).</p></blockquote><p>Adesso dare un nome agli angoli è un semplice <a href="./ffca.html"><strong>esercizio</strong></a>.</p>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};